SELECT CAST(COUNT(CASE WHEN a.hadm_id IN (SELECT hadm_id FROM readmissions) THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.hadm_id), 0) AS readmission_rate, AVG(CASE WHEN a.hadm_id IN (SELECT hadm_id FROM readmissions) THEN a.los ELSE 0 END) AS avg_los_for_readmitted, AVG(CASE WHEN a.hadm_id NOT IN (SELECT hadm_id FROM readmissions) THEN a.los ELSE 0 END) AS avg_los_for_non_readmitted, CAST(COUNT(CASE WHEN a.los > 6 THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.hadm_id), 0) AS proportion_of_stays_over_6_days FROM admissions a;